 echo e(route('admin.institution-onboarding.approve',$item)); ?>"><?php echo csrf_field(); ?><input type="hidden" name="review_note" value="Approved after platform verification."><button class="acad-primary-button">Approve</button></form><form method="POST" action="<?php echo e(route('admin.institution-onboarding.request-info',$item)); ?>"><?php echo csrf_field(); ?><input type="hidden" name="review_note" value="Please provide additional official evidence for this institution claim."><button class="acad-secondary-button">Request info</button></form><form method="POST" action="<?php echo e(route('admin.institution-onboarding.reject',$item)); ?>"><?php echo csrf_field(); ?><input type="hidden" name="review_note" value="The platform could not verify this institution claim."><button class="acad-secondary-button">Reject</button></form><?php if(!$item->university_id): ?><form method="POST" action="<?php echo e(route('admin.institution-onboarding.link-existing',$item)); ?>" class="flex gap-1"><?php echo csrf_field(); ?><input name="university_id" type="number" required placeholder="Existing ID" class="w-28 rounded-lg border-slate-300 text-xs"><button class="acad-secondary-button">Link</button></form><?php endif; ?> <?php elseif($item->university): ?><a href="<?php echo e(route('admin.institution-onboarding.setup',$item->university)); ?>" class="acad-link font-semibold">Continue setup</a><?php endif; ?></div></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_0): ?><tr><td colspan="4" class="px-5 py-12 text-center text-slate-500">No institution requests.</td></tr><?php endif; ?></tbody></table></div><div class="border-t p-4"><?php echo e($requests->links()); ?></div></section>

